-- Add the two user-photographed boxes; no existing products or inventory are overwritten.
BEGIN;
LOCK TABLE public.products,public.product_variants IN SHARE ROW EXCLUSIVE MODE;
DO $guard$ BEGIN IF EXISTS (SELECT 1 FROM public.product_variants WHERE sku='NIS-ACDB-14' AND id<>'60ebef9a-7fc0-57d2-847a-29e0508860b0'::uuid) OR EXISTS (SELECT 1 FROM public.product_variants WHERE sku='NIS-DCDB-21' AND id<>'b233f555-c3c3-5fc3-b611-e61571b08e9c'::uuid) THEN RAISE EXCEPTION 'Target SKU is already assigned; no records changed'; END IF; END $guard$;
UPDATE public.configurator_templates SET preview_settings=jsonb_set(coalesce(preview_settings,'{}'::jsonb),'{reference_presets}',coalesce(preview_settings->'reference_presets','{}'::jsonb)||'{"14": {"id": "14", "spd": "ac-spd-orbit", "mcb": "ac-mcb-empower-c20a", "source": "user-photo-20260922", "product_sku": "NIS-ACDB-14"}}'::jsonb) WHERE id='c0c98f0c-807c-4767-aa60-857df285d183'::uuid;
UPDATE public.configurator_templates SET preview_settings=jsonb_set(coalesce(preview_settings,'{}'::jsonb),'{reference_presets}',coalesce(preview_settings->'reference_presets','{}'::jsonb)||'{"21": {"id": "21", "spd": "dc-spd-winsurge", "mcb": "dc-mcb-siemens-32a", "source": "user-photo-20260922", "product_sku": "NIS-DCDB-21"}}'::jsonb) WHERE id='a4501a4c-2d2f-4c09-8ba9-28978a85a054'::uuid;
DO $verify$ BEGIN IF (SELECT count(*) FROM public.product_variants WHERE sku IN ('NIS-ACDB-14','NIS-DCDB-21'))<>2 THEN RAISE EXCEPTION 'Both listings were not created'; END IF; IF (SELECT count(*) FROM public.components WHERE sku IN ('NIS-VIS-AC-MCB-EMPOWER-C20A','NIS-VIS-AC-SPD-ORBIT'))<>2 THEN RAISE EXCEPTION 'Builder components missing'; END IF; END $verify$;
COMMIT;
